/**
 * `ToUi` is far larger than `ToSource`, which clippy notices. It is
 * deliberate: the whole screen crosses in one action so that the view holds
 * no state to apply a diff against (see [`ActionUi::Render`]). Boxing would
 * not help — UniFFI copies the payload across the boundary either way, so the
 * indirection would cost an allocation and buy nothing.
 */
sealed class Action {
    data class ToUi(
        val `action`: uniffi.phone_state.ActionUi,
    ) : Action() {
        companion object
    }

    data class ToSource(
        val `action`: uniffi.phone_state.ActionSource,
    ) : Action() {
        companion object
    }

    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAction : FfiConverterRustBuffer<Action> {
    override fun read(buf: ByteBuffer): Action =
        when (buf.getInt()) {
            1 -> {
                Action.ToUi(
                    FfiConverterTypeActionUi.read(buf),
                )
            }

            2 -> {
                Action.ToSource(
                    FfiConverterTypeActionSource.read(buf),
                )
            }

            else -> {
                throw RuntimeException("invalid enum value, something is very wrong!!")
            }
        }

    override fun allocationSize(value: Action): ULong =
        when (value) {
            is Action.ToUi -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterTypeActionUi.allocationSize(value.`action`)
                )
            }

            is Action.ToSource -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterTypeActionSource.allocationSize(value.`action`)
                )
            }
        }

    override fun write(
        value: Action,
        buf: ByteBuffer,
    ) {
        when (value) {
            is Action.ToUi -> {
                buf.putInt(1)
                FfiConverterTypeActionUi.write(value.`action`, buf)
                Unit
            }

            is Action.ToSource -> {
                buf.putInt(2)
                FfiConverterTypeActionSource.write(value.`action`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}

